export async function ready(pub, subs, tag = "p", timeoutMs = 15_000) {
  const got = new Set();
  // AFTER the real subscriptions, on the same connections: ordering makes the probe a proof for them too
  subs.forEach((s, i) => s.sub(`_bench.probe.${tag}.${i}`, () => got.add(i)));
  await Promise.all(subs.map((s) => s.flush()));
  const end = Date.now() + timeoutMs;
  while (got.size < subs.length) {
    if (Date.now() > end) throw new Error(`probe: only ${got.size}/${subs.length} subscribers reachable`);
    subs.forEach((_, i) => got.has(i) || pub.pub(`_bench.probe.${tag}.${i}`, Buffer.from("probe")));
    await pub.flush();
    await new Promise((r) => setTimeout(r, 20));
  }
}

export function lossReport(sent, receivedSeqs) {
  const seen = new Map();
  let unexpected = 0;
  for (const n of receivedSeqs) {
    if (!Number.isInteger(n) || n < 0 || n >= sent) { unexpected++; continue; }
    seen.set(n, (seen.get(n) ?? 0) + 1);
  }
  const duplicates = [...seen.values()].filter((c) => c > 1).length;
  const ranges = [];
  for (let i = 0; i < sent; i++) {
    if (seen.has(i)) continue;
    const last = ranges.at(-1);
    if (last && last[1] === i - 1) last[1] = i;
    else ranges.push([i, i]);
  }
  return { received: seen.size, lost: sent - seen.size, duplicates, unexpected, ranges };
}

const r = lossReport(10, [0, 1, 2, 2, 6, 7, 8, 9]);
console.assert(r.lost === 3 && r.duplicates === 1 && JSON.stringify(r.ranges) === "[[3,5]]");

